          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "resuspend",
          "name": "Resuspend in Resuspension Buffer (vortex)",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "pellet" }
        },
        {
          "stepId": "lyse",
          "name": "Add Lysis Buffer, invert 6×, incubate 5 min",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "resuspend", "offsetSeconds": 30 }
        },
        {
          "stepId": "neutralize",
          "name": "Add Neutralization Buffer, invert, spin microcentrifuge 10 min",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "lyse", "offsetSeconds": 30 }
        },
        {
          "stepId": "spin_column_load",
          "name": "Load lysate onto spin column, spin 1 min",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 60 },
          "startTrigger": { "type": "afterStep", "stepId": "neutralize" }
        },
        {
          "stepId": "wash",
          "name": "Wash column with 700 µL Wash Buffer, spin 1 min",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 60 },
          "startTrigger": { "type": "afterStep", "stepId": "spin_column_load", "offsetSeconds": 30 }
        },
        {
          "stepId": "dry",
          "name": "Spin empty column 2 min to dry",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "wash" }
        },
        {
          "stepId": "elute",
          "name": "Add Elution Buffer, wait 1 min, spin 1 min",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "dry", "offsetSeconds": 60 }
        },
        {
          "stepId": "measure_dna",
          "name": "Measure DNA concentration",
          "task": "spectrophotometer",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "afterStep", "stepId": "elute" }
        }
      ]
    },
    {
      "trackId": "gel_prep",
      "name": "Gel Casting",
      "steps": [
        {
          "stepId": "weigh_agarose",
          "name": "Weigh 0.5 g agarose into 50 mL TAE",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 60 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "microwave_agarose",
          "name": "Microwave 2 min, swirl once until dissolved",
          "task": "microwave",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "weigh_agarose" }
        },
        {
          "stepId": "cool_gel",
          "name": "Cool flask on bench 10 min",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "microwave_agarose" }
        },
        {
          "stepId": "add_stain_pour",
          "name": "Add 5 µL stain, pour gel into tray with comb",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "cool_gel" }
        },
        {
          "stepId": "set_gel",
          "name": "Let gel set 30 min at room temperature",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 1800 },
          "startTrigger": { "type": "afterStep", "stepId": "add_stain_pour" }
        },
        {
          "stepId": "remove_comb_load",
          "name": "Remove comb, place gel in rig under TAE",
          "task": "gel_rig",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "set_gel" }
