          "duration": { "type": "fixed", "seconds": 30 },
          "startTrigger": { "type": "afterStep", "stepId": "inactivate_65", "offsetSeconds": 30 }
        },
        {
          "stepId": "load_gel",
          "name": "Load 10 µL digest and 5 µL ladder per well",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 300 },
